import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Extension Security Model","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/security.md","filePath":"extensions/security.md"}'),s={name:"extensions/security.md"};function r(n,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="extension-security-model" tabindex="-1">Extension Security Model <a class="header-anchor" href="#extension-security-model" aria-label="Permalink to &quot;Extension Security Model&quot;">​</a></h1><p>Palexplorer uses defense-in-depth to protect users from malicious extensions.</p><h2 id="bundled-vs-community" tabindex="-1">Bundled vs Community <a class="header-anchor" href="#bundled-vs-community" aria-label="Permalink to &quot;Bundled vs Community&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Bundled (<code>@palexplorer/*</code>)</th><th>Community</th></tr></thead><tbody><tr><td><strong>Execution</strong></td><td>In-process (trusted)</td><td>Worker thread sandbox (64 MB)</td></tr><tr><td><strong>Signature</strong></td><td>Not required</td><td>Ed25519 signature required</td></tr><tr><td><strong>AST scan</strong></td><td>Optional</td><td>Mandatory</td></tr><tr><td><strong>Permission approval</strong></td><td>Automatic</td><td>User must approve</td></tr><tr><td><strong>Maintained by</strong></td><td>Palexplorer team</td><td>Third-party developers</td></tr></tbody></table><h2 id="security-layers" tabindex="-1">Security Layers <a class="header-anchor" href="#security-layers" aria-label="Permalink to &quot;Security Layers&quot;">​</a></h2><h3 id="_1-manifest-validation" tabindex="-1">1. Manifest Validation <a class="header-anchor" href="#_1-manifest-validation" aria-label="Permalink to &quot;1. Manifest Validation&quot;">​</a></h3><p>Before loading, the manifest is validated:</p><ul><li>Name, version, description within limits</li><li>Main file is <code>.js</code>, no path traversal</li><li>Permissions from valid set (max 10)</li><li>Hooks from valid set (max 20)</li></ul><h3 id="_2-ast-security-analysis" tabindex="-1">2. AST Security Analysis <a class="header-anchor" href="#_2-ast-security-analysis" aria-label="Permalink to &quot;2. AST Security Analysis&quot;">​</a></h3><p>Community extensions are scanned with an AST analyzer (acorn + acorn-walk) that detects:</p><p><strong>Blocked imports:</strong></p><ul><li><code>child_process</code>, <code>cluster</code>, <code>dgram</code>, <code>dns</code>, <code>http2</code>, <code>inspector</code>, <code>net</code>, <code>repl</code>, <code>tls</code>, <code>vm</code>, <code>worker_threads</code></li></ul><p><strong>Dangerous patterns:</strong></p><ul><li><code>eval()</code> and <code>new Function()</code></li><li>Dynamic <code>import()</code> and <code>require()</code> with non-literal paths</li><li><code>process.exit</code>, <code>process.kill</code>, <code>process.env</code> mutation</li><li>Prototype pollution (<code>__proto__</code>, <code>constructor</code>, <code>prototype</code>)</li></ul><h3 id="_3-ed25519-signature-verification" tabindex="-1">3. Ed25519 Signature Verification <a class="header-anchor" href="#_3-ed25519-signature-verification" aria-label="Permalink to &quot;3. Ed25519 Signature Verification&quot;">​</a></h3><p>Extensions must be signed with the developer&#39;s Ed25519 key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ext</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-extension</span></span></code></pre></div><p>The signature covers <code>extension.json</code> + <code>index.js</code>. Unsigned extensions are rejected (unless <code>extensionRequireSignature=false</code> in dev mode).</p><h3 id="_4-integrity-hashing" tabindex="-1">4. Integrity Hashing <a class="header-anchor" href="#_4-integrity-hashing" aria-label="Permalink to &quot;4. Integrity Hashing&quot;">​</a></h3><p>After installation, a SHA-256 hash of the manifest and entry point is stored. On every load, the hash is rechecked — if any file was modified, the extension is blocked.</p><h3 id="_5-permission-approval" tabindex="-1">5. Permission Approval <a class="header-anchor" href="#_5-permission-approval" aria-label="Permalink to &quot;5. Permission Approval&quot;">​</a></h3><p>Users must explicitly approve permissions before an extension runs for the first time. If an update adds new permissions, approval is required again.</p><h3 id="_6-worker-thread-sandbox" tabindex="-1">6. Worker Thread Sandbox <a class="header-anchor" href="#_6-worker-thread-sandbox" aria-label="Permalink to &quot;6. Worker Thread Sandbox&quot;">​</a></h3><p>Community extensions run in an isolated Worker thread with:</p><ul><li><strong>64 MB memory limit</strong></li><li><strong>No access</strong> to the main process</li><li><strong>No access</strong> to private keys, seed phrases, or encryption keys</li><li><strong>No access</strong> to core config (identity, friends, servers)</li><li><strong>No access</strong> to other extensions&#39; data</li><li><strong>File paths scoped</strong> to declared shares only</li></ul><h3 id="_7-auto-disable" tabindex="-1">7. Auto-Disable <a class="header-anchor" href="#_7-auto-disable" aria-label="Permalink to &quot;7. Auto-Disable&quot;">​</a></h3><p>Extensions that fail to load 3 consecutive times are automatically disabled to prevent boot loops.</p><h2 id="what-extensions-cannot-access" tabindex="-1">What Extensions Cannot Access <a class="header-anchor" href="#what-extensions-cannot-access" aria-label="Permalink to &quot;What Extensions Cannot Access&quot;">​</a></h2><ul><li>Ed25519 private keys or seed phrases</li><li>XChaCha20-Poly1305 encryption keys</li><li>PAL/1.0 protocol internals</li><li>Raw BitTorrent/WebTorrent connections</li><li>Core config (identity, friends, servers)</li><li>Other extensions&#39; data</li><li>Files outside share paths</li><li>Arbitrary shell commands (except declared <code>exec:&lt;command&gt;</code>)</li></ul>',29)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
